		let mid = Math.floor((start + end) / 2);

		if (nums[mid] === target) return mid;

		// If the left half is sorted 
		if (nums[start] <= nums[mid]){
			// the left half contains the target
			if (nums[start] <= target && target < nums[mid]){
				end = mid - 1;
			} else {
				// or it contains on the right
				start = mid + 1;
			}
		// The right side is sorted	
		} else {
			// The right side contains the target 
			if (nums[mid] < target && target <= nums[end]){
				start = mid + 1;
			// or the target is on the left side
			} else {
				end = mid - 1;
			}
		}
	}
  // Target not found
	return -1;
};

