function countAndSay(n) {
  if (n === 1) return '1';
  let prev = countAndSay(n - 1);
  let curr = '';
  let count = 1;
  for (let i = 0; i < prev.length; i++) {
    while (prev[i] === prev[i + 1]) {
      count++;
      i++;
    }
    curr += `${count}${prev[i]}`;
    count = 1;
  }

  return curr;
}

